90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	    const TAG_PRINTABLE_STRING: u8 = 0x13;
118	    const TAG_BMP_STRING: u8 = 0x1E;
119	
120	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
121	    /// length encodings and truncated data.
122	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
123	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
124	        if tag & 0x1F == 0x1F {
125	            return Err("multi-byte tags are not supported".to_string());
126	        }
127	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
128	        let (len, header_len) = match first_len {
129	            0x00..=0x7F => (first_len as usize, 2),
130	            0x80 => return Err("indefinite length is not valid DER".to_string()),
131	            0xFF => return Err("reserved length byte".to_string()),
132	            long => {
133	                let n = (long & 0x7F) as usize;
134	                if !(1..=4).contains(&n) {
135	                    return Err("length is too large".to_string());
136	                }
137	                let bytes = buf
138	                    .get(2..2 + n)
139	                    .ok_or_else(|| "truncated long length".to_string())?;
140	                if bytes[0] == 0 {
141	                    return Err("non-minimal length encoding".to_string());
142	                }
143	                let mut len = 0usize;
144	                for &b in bytes {
145	                    len = len
146	                        .checked_shl(8)
147	                        .and_then(|l| l.checked_add(b as usize))
148	                        .ok_or_else(|| "length overflow".to_string())?;
149	                }
150	                if len < 0x80 {
151	                    return Err("non-minimal length encoding".to_string());
152	                }
153	                (len, 2 + n)
154	            }
155	        };
156	        let total = header_len
157	            .checked_add(len)
158	            .filter(|&t| t <= buf.len())
159	            .ok_or_else(|| "truncated TLV content".to_string())?;
160	        Ok((
161	            Tlv {
162	                tag,
163	                content: &buf[header_len..total],
164	            },
165	            &buf[total..],
166	        ))
167	    }
168	
169	    fn read_tagged<'a>(
170	        buf: &'a [u8],
171	        tag: u8,
172	        what: &str,
173	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
174	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
175	        if tlv.tag != tag {
176	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
177	        }
178	        Ok((tlv, rest))
179	    }
180	
181	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
182	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
183	        // signatureValue BIT STRING } — and nothing trailing.
184	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
185	        if !rest.is_empty() {
186	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
187	        }
188	
189	        let c = cert.content;
190	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
191	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
192	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
193	        let (sig_value, c) = read_tlv(c)?;
194	        if sig_value.tag != TAG_BIT_STRING {
195	            return Err("signature must be a BIT STRING".to_string());
196	        }
197	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
198	            return Err("invalid signature BIT STRING".to_string());
199	        }
200	        if !c.is_empty() {
201	            return Err("trailing data in Certificate".to_string());
202	        }
203	
204	        // TBSCertificate ::= SEQUENCE {
205	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
206	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
207	        let t = tbs.content;
208	        let (first, t2) = read_tlv(t)?;
209	        let (version, t) = if first.tag == 0xA0 {
210	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
211	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
212	                return Err("invalid certificate version".to_string());
213	            }
214	            (ver.content[0], t2)
215	        } else {
216	            // No explicit version: v1 certificate.
217	            (0u8, t)
218	        };
219	
220	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
221	        let t = t3;
222	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
223	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
224	        if tbs_alg != outer_alg {
225	            return Err(mismatch_message(&outer_alg, &tbs_alg));
226	        }
227	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
228	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
229	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
230	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
231	        check_spki(spki)?;
232	        // Optional tail of TBSCertificate, in a fixed order:
233	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
234	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
235	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
236	        //                                             and the last field)
237	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
238	        // skipped, reordered or dropped. The extensions interior is decoded in
239	        // full by `check_extensions`; the unique IDs carry BIT STRING content
240	        // directly (implicit tagging), validated by `check_bit_string`.
241	        let mut t = t_after_spki;
242	        let mut issuer_uid_seen = false;
243	        let mut subject_uid_seen = false;
244	        let mut extensions_present = false;
245	        while !t.is_empty() {
246	            let tag_hint = t.first().copied();
247	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
248	                Some(0x81) => format!("issuerUniqueID: {e}"),
249	                Some(0x82) => format!("subjectUniqueID: {e}"),
250	                // A truncated field whose tag is already readable can still
251	                // be located: tag 0xA3 is the extensions field.
252	                Some(0xA3) => format!("extensions field: {e}"),
253	                _ => e,
254	            })?;
255	            match field.tag {
256	                0x81 | 0x82 => {
257	                    let what = if field.tag == 0x81 {
258	                        "issuerUniqueID"
259	                    } else {
260	                        "subjectUniqueID"
261	                    };
262	                    if version < 1 {
263	                        return Err(format!(
264	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
265	                        ));
266	                    }
267	                    if extensions_present {
268	                        return Err(format!(
269	                            "{what} must appear before the extensions field, \
270	                             which is the last field of tbsCertificate"
271	                        ));
272	                    }
273	                    if field.tag == 0x81 {
274	                        if issuer_uid_seen {
275	                            return Err("duplicate issuerUniqueID field".to_string());
276	                        }
277	                        if subject_uid_seen {
278	                            return Err(
279	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
280	                            );
281	                        }
282	                        issuer_uid_seen = true;
283	                    } else if subject_uid_seen {
284	                        return Err("duplicate subjectUniqueID field".to_string());
285	                    } else {
286	                        subject_uid_seen = true;
287	                    }
288	                    check_bit_string(field.content, what)?;
289	                }
290	                0xA1 | 0xA2 => {
291	                    let what = if field.tag == 0xA1 {
292	                        "issuerUniqueID"
293	                    } else {
294	                        "subjectUniqueID"
295	                    };
296	                    return Err(format!(
297	                        "{what} must be an implicitly tagged primitive BIT STRING \
298	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
299	                         and is not allowed",
300	                        field.tag - 0x20,
301	                        field.tag
302	                    ));
303	                }
304	                0xA3 => {
305	                    if extensions_present {
306	                        return Err("duplicate extensions field".to_string());
307	                    }
308	                    if version != 2 {
309	                        let name = if version == 0 {
310	                            "v1"
311	                        } else {
312	                            "v2"
313	                        };
314	                        return Err(format!(
315	                            "extensions are only allowed in v3 certificates, this is {name}"
316	                        ));
317	                    }
318	                    check_extensions(field.content)?;
319	                    extensions_present = true;
320	                }
321	                other => {
322	                    return Err(format!(
323	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
324	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
325	                         are allowed there, and extensions must be last"
326	                    ));
327	                }
328	            }
329	            t = rest;
330	        }
331	
332	        let serial_hex = format_serial(serial.content)?;
333	        let issuer = format_name(issuer, "issuer")?;
334	        let subject = format_name(subject, "subject")?;
335	
336	        let v = validity.content;
337	        let (nb, v2) = read_tlv(v)?;
338	        let (na, v3) = read_tlv(v2)?;
339	        if !v3.is_empty() {
340	            return Err("trailing data in validity".to_string());
341	        }
342	        let not_before = format_time(nb)?;
343	        let not_after = format_time(na)?;
344	
345	        Ok(Cert {
346	            subject,
347	            issuer,
348	            serial_hex,
349	            not_before,
350	            not_after,
351	        })
352	    }
353	
354	    /// Validate the content of the extensions field, i.e. the bytes wrapped
355	    /// by `[3] EXPLICIT`:
356	    ///
357	    /// ```text
358	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
359	    /// Extension  ::= SEQUENCE {
360	    ///   extnID    OBJECT IDENTIFIER,
361	    ///   critical  BOOLEAN DEFAULT FALSE,
362	    ///   extnValue OCTET STRING }
363	    /// ```
364	    ///
365	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
366	    /// Every extension must contain its OID and OCTET STRING in that order,
367	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
368	    /// Extension contents are never interpreted: unknown but well-formed
369	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
370	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
371	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
372	        if !rest.is_empty() {
373	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
374	        }
375	        if list.content.is_empty() {
376	            return Err("extensions SEQUENCE is empty".to_string());
377	        }
378	
379	        let mut buf = list.content;
380	        while !buf.is_empty() {
381	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
382	            buf = rest;
383	
384	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
385	            parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
386	
387	            // critical is optional; whatever stands between the OID and the
388	            // OCTET STRING must be exactly one BOOLEAN if it is present.
389	            let (maybe_bool, after_critical) = read_tlv(after_oid)
390	                .map_err(|e| format!("extension after OID: {e}"))?;
391	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
392	                match maybe_bool.content {
393	                    [0xFF] => {}
394	                    [0x00] => {
395	                        return Err(
396	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
397	                                .to_string()
398	                        )
399	                    }
400	                    _ => {
401	                        return Err(
402	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
403	                        )
404	                    }
405	                }
406	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
407	            } else {
408	                // Not a BOOLEAN: this element must itself be the extnValue.
409	                if maybe_bool.tag != TAG_OCTET_STRING {
410	                    return Err(format!(
411	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
412	                         got tag 0x{:02X}",
413	                        maybe_bool.tag
414	                    ));
415	                }
416	                (maybe_bool, after_critical)
417	            };
418	            // An empty OCTET STRING is legal; its bytes are not interpreted.
419	            let _ = octets.content;
420	            if !after_octets.is_empty() {
421	                return Err("trailing data in extension".to_string());
422	            }
423	        }
424	        Ok(())
425	    }
426	
427	    /// SubjectPublicKeyInfo ::= SEQUENCE {
428	    ///   algorithm        AlgorithmIdentifier,
429	    ///   subjectPublicKey BIT STRING }
430	    /// Nothing may be missing and no extra elements may follow.
431	    fn check_spki(spki: Tlv) -> Result<(), String> {
432	        let (alg, rest) = read_tagged(
433	            spki.content,
434	            TAG_SEQUENCE,
435	            "subjectPublicKeyInfo algorithm identifier",
436	        )?;
437	        check_algorithm_identifier(alg)?;
438	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
439	        check_bit_string(key.content, "subjectPublicKey")?;
440	        if !rest.is_empty() {
441	            return Err("trailing data in subjectPublicKeyInfo".to_string());
442	        }
443	        Ok(())
444	    }
445	
446	    /// Why the content of an AlgorithmIdentifier SEQUENCE failed the shared
447	    /// structural check in `split_algorithm_identifier`. Each variant carries
448	    /// only the raw facts; every reader maps them onto its own established
449	    /// error wording (the public-key position names "algorithm OID" and
450	    /// "algorithm parameters", the signature algorithm positions name their
451	    /// own location).
452	    enum AlgIdError {
453	        /// The leading OID element could not be read as one complete TLV.
454	        OidRead(String),
455	        /// The first element is present but is not an OID.
456	        OidTag(u8),
457	        /// The OID element exists but its content is not a valid OID
458	        /// (empty, truncated or non-minimal base-128 arcs).
459	        OidContent(String),
460	        /// A parameter element follows the OID but cannot be read as one
461	        /// complete TLV.
462	        ParamsRead(String),
463	        /// Bytes remain after the parameter element: parameters are one
464	        /// OPTIONAL element, never several.
465	        ExtraAfterParams,
466	    }
467	
468	    /// Split the content of an AlgorithmIdentifier SEQUENCE into its
469	    /// algorithm OID and optional parameters, enforcing the structure every
470	    /// reader of an algorithm identifier shares:
471	    ///
472	    /// ```text
473	    /// AlgorithmIdentifier ::= SEQUENCE {
474	    ///   algorithm  OBJECT IDENTIFIER,
475	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
476	    /// ```
477	    ///
478	    /// The content must start with one complete, shortest-encoded OID,
479	    /// followed by either nothing or exactly one complete DER parameter
480	    /// value, and nothing after that. Absent parameters and an explicit NULL
481	    /// are both accepted and the parameter content is never interpreted for
482	    /// any particular algorithm; an unknown but well-formed OID is accepted.
483	    /// The parameter TLV is returned as its full original encoding (tag,
484	    /// length and content), sliced straight from the input, so callers that
485	    /// compare two identifiers can do so at the DER byte level.
486	    fn split_algorithm_identifier(
487	        content: &[u8],
488	    ) -> Result<(Tlv<'_>, Option<&[u8]>), AlgIdError> {
489	        let (oid, rest) = read_tlv(content).map_err(AlgIdError::OidRead)?;
490	        if oid.tag != TAG_OID {
491	            return Err(AlgIdError::OidTag(oid.tag));
492	        }
493	        parse_oid(oid.content).map_err(AlgIdError::OidContent)?;
494	        let params = if rest.is_empty() {
495	            None
496	        } else {
497	            let (_params, after) = read_tlv(rest).map_err(AlgIdError::ParamsRead)?;
498	            if !after.is_empty() {
499	                return Err(AlgIdError::ExtraAfterParams);
500	            }
501	            // Keep the full parameter TLV (tag, length and content), sliced
502	            // straight from the enclosing content; `read_tlv` already proved
503	            // it is a complete value.
504	            Some(&rest[..rest.len() - after.len()])
505	        };
506	        Ok((oid, params))
507	    }
508	
509	    /// Validate the AlgorithmIdentifier inside SubjectPublicKeyInfo: the
510	    /// shared structure from `split_algorithm_identifier`, reported with the
511	    /// public-key position's own wording.
512	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
513	        split_algorithm_identifier(alg.content)
514	            .map(|_| ())
515	            .map_err(|e| match e {
516	                AlgIdError::OidRead(e) => format!("algorithm OID: {e}"),
517	                AlgIdError::OidTag(tag) => {
518	                    format!("expected algorithm OID (tag 0x06), got 0x{tag:02X}")
519	                }
520	                AlgIdError::OidContent(e) => format!("algorithm OID: {e}"),
521	                AlgIdError::ParamsRead(e) => format!("algorithm parameters: {e}"),
522	                AlgIdError::ExtraAfterParams => "multiple algorithm parameters".to_string(),
523	            })
524	    }
525	
526	    /// One of the certificate's two signature algorithm descriptions, kept as
527	    /// raw slices so two copies can be compared at the DER byte level: the OID
528	    /// content (arcs in their shortest encoding) and the complete parameter
529	    /// TLV (tag, length and content), or no parameter at all. An absent
530	    /// parameter and an explicit NULL are different representations.
531	    #[derive(Clone, Copy, PartialEq, Eq)]
532	    struct SignatureAlgorithm<'a> {
533	        oid_content: &'a [u8],
534	        params: Option<&'a [u8]>,
535	    }
536	
537	    /// Parse and fully validate one signatureAlgorithm SEQUENCE, applying the
538	    /// shared AlgorithmIdentifier structure from `split_algorithm_identifier`
539	    /// and keeping the raw pieces for the byte-level comparison of the two
540	    /// copies. `loc` names which of the two copies is being checked ("outer
541	    /// signatureAlgorithm" or the copy inside tbsCertificate) and prefixes
542	    /// every error message.
543	    fn parse_signature_algorithm<'a>(
544	        alg: Tlv<'a>,
545	        loc: &str,
546	    ) -> Result<SignatureAlgorithm<'a>, String> {
547	        let (oid, params) = split_algorithm_identifier(alg.content).map_err(|e| match e {
548	            AlgIdError::OidRead(e) => format!("{loc}: {e}"),
549	            AlgIdError::OidTag(tag) => format!(
550	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{tag:02X}"
551	            ),
552	            AlgIdError::OidContent(e) => format!("{loc}: {e}"),
553	            AlgIdError::ParamsRead(e) => format!("{loc}: algorithm parameters: {e}"),
554	            AlgIdError::ExtraAfterParams => {
555	                format!("{loc}: extra element after the algorithm parameters")
556	            }
557	        })?;
558	        Ok(SignatureAlgorithm {
559	            oid_content: oid.content,
560	            params,
561	        })
562	    }
563	
564	    /// Describe the disagreement between the outer signatureAlgorithm and the
565	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
566	    /// fail to name the same algorithm or the same parameter representation.
567	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
568	        const OUTER: &str = "the outer signatureAlgorithm";
569	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
570	        if outer.oid_content != inner.oid_content {
571	            let outer_oid = parse_oid(outer.oid_content)
572	                .map(|arcs| arcs_to_string(&arcs))
573	                .unwrap_or_else(|_| "?".to_string());
574	            let inner_oid = parse_oid(inner.oid_content)
575	                .map(|arcs| arcs_to_string(&arcs))
576	                .unwrap_or_else(|_| "?".to_string());
577	            return format!(
578	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
579	                 names OID {inner_oid}"
580	            );
581	        }
582	        match (outer.params, inner.params) {
583	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
584	                format!(
585	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
586	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
587	                    hex_of(outer_params),
588	                    hex_of(inner_params),
589	                )
590	            }
591	            (Some(_), None) => format!(
592	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
593	                 (an absent parameter and an explicit value are different representations)"
594	            ),
595	            (None, Some(_)) => format!(
596	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
597	                 (an absent parameter and an explicit value are different representations)"
598	            ),
599	            // PartialEq already proved the copies unequal; reaching any other
600	            // arm here would be a logic error rather than a malformed cert.
601	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
602	                .to_string(),
603	        }
604	    }
