606	    fn hex_of(bytes: &[u8]) -> String {
607	        let mut s = String::with_capacity(bytes.len() * 2);
608	        for b in bytes {
609	            write!(s, "{b:02X}").unwrap();
610	        }
611	        s
612	    }
