614	    /// Validate the DER content of a BIT STRING: one leading byte counting
615	    /// unused bits (0..=7), and when the count is nonzero those low bits of
616	    /// the final data byte must all be zero. An empty bit string is only
617	    /// legal with a zero count.
618	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
619	        let unused = *content
620	            .first()
621	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
622	        if unused > 7 {
623	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
624	        }
625	        let data = &content[1..];
626	        if data.is_empty() {
627	            if unused != 0 {
628	                return Err(format!(
629	                    "{what} BIT STRING declares {unused} unused bits but has no data"
630	                ));
631	            }
632	            return Ok(());
633	        }
634	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
635	            return Err(format!(
636	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
637	            ));
638	        }
639	        Ok(())
640	    }
