642	    /// Render the serial number as upper-case hex, matching the integer value
643	    /// (a DER sign-padding 0x00 byte is not part of the number).
644	    fn format_serial(content: &[u8]) -> Result<String, String> {
645	        if content.is_empty() {
646	            return Err("empty serial number".to_string());
647	        }
648	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
649	            return Err("non-minimal serial number encoding".to_string());
650	        }
651	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
652	            return Err("non-minimal serial number encoding".to_string());
653	        }
654	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
655	            return Err("negative serial number".to_string());
656	        }
657	        let digits = if content.len() > 1 && content[0] == 0x00 {
658	            &content[1..]
659	        } else {
660	            content
661	        };
662	        let mut s = String::with_capacity(digits.len() * 2);
663	        for b in digits {
664	            write!(s, "{b:02X}").unwrap();
665	        }
666	        if s.is_empty() {
667	            s.push_str("00");
668	        }
669	        Ok(s)
670	    }
