672	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
673	    /// multi-valued RDNs joined with '+'). Values of known attribute types
674	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
675	    /// when their tag has a text decoder; a known type carrying any other
676	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
677	    /// name and uses the '#' form carrying the value's full DER encoding in
678	    /// hex. Attributes without a known short name use their dotted OID with
679	    /// the same '#' form.
680	    ///
681	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
682	    /// encodings must be sorted by their full encoding bytes (tag, then
683	    /// length, then content — the encoding, never the display name, dotted
684	    /// OID text or decoded value). The check is per RDN; it never reorders
685	    /// the members itself. `what` names the name being checked ("subject" or
686	    /// "issuer") so an ordering failure identifies it in the error message.
687	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
688	        let mut rdn_buf = name.content;
689	        let mut rdns: Vec<String> = Vec::new();
690	        while !rdn_buf.is_empty() {
691	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
692	            rdn_buf = rest;
693	
694	            let mut atv_buf = set.content;
695	            let mut parts = Vec::new();
696	            // Raw full encoding (tag, length and content) of each member of
697	            // this SET OF, straight from the certificate: DER SET OF ordering
698	            // compares the complete member encodings byte for byte. Equal
699	            // encodings may legitimately repeat and stay adjacent.
700	            let mut members: Vec<&[u8]> = Vec::new();
701	            while !atv_buf.is_empty() {
702	                let atv_start = atv_buf;
703	                let (atv, rest) =
704	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
705	                atv_buf = rest;
706	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
707	
708	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
709	                let (value, after_value) = read_tlv(after_oid)?;
710	                if !after_value.is_empty() {
711	                    return Err("trailing data in attribute value".to_string());
712	                }
713	
714	                let oid_arcs = parse_oid(oid.content)?;
715	
716	                // The value's own type rules apply before any display decision:
717	                // a PrintableString must hold only the RFC 5280 PrintableString
718	                // alphabet, and a BMPString must hold whole 16-bit BMP
719	                // characters, whether the attribute later renders as text for a
720	                // known short name or as '#'-hex for an unknown type. The hex
721	                // form must never let an illegal byte through, and an illegal
722	                // byte cannot be dropped or replaced. An empty value stays
723	                // legal. `what` names the offending name ("subject"/"issuer").
724	                if value.tag == TAG_PRINTABLE_STRING
725	                    && !is_printable_string(value.content)
726	                {
727	                    return Err(format!(
728	                        "{what} name: PrintableString attribute value contains an illegal \
729	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
730	                         allowed)"
731	                    ));
732	                }
733	                if value.tag == TAG_BMP_STRING {
734	                    check_bmp_string(value.content, what)?;
735	                }
736	
737	                match oid_short_name(&oid_arcs) {
738	                    Some(label) => {
739	                        if is_text_value_tag(value.tag) {
740	                            // Supported string type: decode to escaped text.
741	                            // A decode failure (e.g. invalid UTF-8) means the
742	                            // certificate is corrupt; it must not be salvaged
743	                            // by falling back to the hex form.
744	                            let text = decode_attribute_value(value.tag, value.content)?;
745	                            parts.push(format!("{label}={}", escape_value(&text)));
746	                        } else {
747	                            // Known type but a legal value with no text decoder
748	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
749	                            // and show the full original DER encoding as '#'-hex.
750	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
751	                        }
752	                    }
753	                    None => {
754	                        // Unknown attribute type: RFC 4514 requires the form
755	                        // OID=#hex, where the hex is the full DER encoding
756	                        // (tag, length and content) of the attribute value.
757	                        // Showing the value as hex does not bypass its type
758	                        // rules: UTF8String content must be valid UTF-8, a
759	                        // PrintableString must keep to its alphabet and a
760	                        // BMPString must hold legal BMP characters, checks
761	                        // already performed above before this match.
762	                        if value.tag == 0x0C {
763	                            std::str::from_utf8(value.content)
764	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
765	                        }
766	                        let hex = value_hex(after_oid, after_value);
767	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
768	                    }
769	                }
770	            }
771	            if parts.is_empty() {
772	                return Err("empty RelativeDistinguishedName".to_string());
773	            }
774	            check_rdn_der_order(&members, what)?;
775	            rdns.push(parts.join("+"));
776	        }
777	        rdns.reverse();
778	        Ok(rdns.join(","))
779	    }
