781	    /// Validate one RDN as a DER SET OF: every member's complete
782	    /// AttributeTypeAndValue encoding must be less than or equal to the next
783	    /// one under ordinary byte ordering of tag, length and content. The
784	    /// comparison runs on the raw encodings only — CN/O short names, dotted
785	    /// OID text and decoded values never enter into it — and equal adjacent
786	    /// members (duplicate attributes) are allowed. The members are never
787	    /// reordered to make an unsorted input pass. `what` is "subject" or
788	    /// "issuer" and identifies the offending name in the error message.
789	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
790	        for pair in members.windows(2) {
791	            if pair[0] > pair[1] {
792	                return Err(format!(
793	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
794	                     are not encoded in DER SET OF order (the members must be sorted by \
795	                     their complete DER encoding bytes: tag, then length, then content)"
796	                ));
797	            }
798	        }
799	        Ok(())
800	    }
