802	    /// Uppercase hex of one complete value TLV, sliced straight from the
803	    /// input bytes (`around` ends at `rest`). The original tag and length
804	    /// bytes survive verbatim, including a legal long-form length; nothing is
805	    /// re-encoded and content alone is never emitted.
806	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
807	        let tlv_len = around.len() - rest.len();
808	        let mut hex = String::with_capacity(tlv_len * 2);
809	        for b in &around[..tlv_len] {
810	            write!(hex, "{b:02X}").unwrap();
811	        }
812	        hex
813	    }
814	
815	    /// Tags whose attribute values have a direct text decoding in
816	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
817	    /// legal non-text value for display purposes and is rendered as '#'-hex.
818	    fn is_text_value_tag(tag: u8) -> bool {
819	        matches!(
820	            tag,
821	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
822	        )
823	    }
824	
825	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
826	        if content.is_empty() {
827	            return Err("empty OID".to_string());
828	        }
829	        let mut arcs = Vec::new();
830	        // The first subidentifier encodes the first two arcs as
831	        // 40*first + second and is itself a base-128 quantity, so it can
832	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
833	        let mut i = 0;
834	        let first = read_oid_arc(content, &mut i)?;
835	        match first {
836	            0..=39 => {
837	                arcs.push(0);
838	                arcs.push(first);
839	            }
840	            40..=79 => {
841	                arcs.push(1);
842	                arcs.push(first - 40);
843	            }
844	            _ => {
845	                arcs.push(2);
846	                arcs.push(first - 80);
847	            }
848	        }
849	        while i < content.len() {
850	            arcs.push(read_oid_arc(content, &mut i)?);
851	        }
852	        Ok(arcs)
853	    }
854	
855	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
856	    /// continuation bytes and non-minimal encodings.
857	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
858	        let start = *i;
859	        let mut value = 0u64;
860	        loop {
861	            let b = *content
862	                .get(*i)
863	                .ok_or_else(|| "truncated OID arc".to_string())?;
864	            value = value
865	                .checked_mul(128)
866	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
867	                .ok_or_else(|| "OID arc overflow".to_string())?;
868	            *i += 1;
869	            if b & 0x80 == 0 {
870	                break;
871	            }
872	        }
873	        if *i - start > 1 && content[start] == 0x80 {
874	            return Err("non-minimal OID arc encoding".to_string());
875	        }
876	        Ok(value)
877	    }
878	
879	    fn arcs_to_string(arcs: &[u64]) -> String {
880	        arcs.iter()
881	            .map(u64::to_string)
882	            .collect::<Vec<_>>()
883	            .join(".")
884	    }
