887	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
888	        let name = match arcs {
889	            [2, 5, 4, 3] => "CN",
890	            [2, 5, 4, 4] => "SN",
891	            [2, 5, 4, 5] => "serialNumber",
892	            [2, 5, 4, 6] => "C",
893	            [2, 5, 4, 7] => "L",
894	            [2, 5, 4, 8] => "ST",
895	            [2, 5, 4, 9] => "STREET",
896	            [2, 5, 4, 10] => "O",
897	            [2, 5, 4, 11] => "OU",
898	            [2, 5, 4, 12] => "title",
899	            [2, 5, 4, 17] => "postalAddress",
900	            [2, 5, 4, 18] => "postalCode",
901	            [2, 5, 4, 20] => "telephoneNumber",
902	            [2, 5, 4, 42] => "givenName",
903	            [2, 5, 4, 43] => "initials",
904	            [2, 5, 4, 44] => "generationQualifier",
905	            [2, 5, 4, 46] => "dnQualifier",
906	            [2, 5, 4, 65] => "pseudonym",
907	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
908	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
