915	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
916	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
917	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
918	    /// An empty value passes, preserving the existing acceptance of empty
919	    /// contents.
920	    fn is_printable_string(content: &[u8]) -> bool {
921	        content.iter().all(|&b| matches!(
922	            b,
923	            b'A'..=b'Z'
924	                | b'a'..=b'z'
925	                | b'0'..=b'9'
926	                | b' '
927	                | b'\''
928	                | b'('
929	                | b')'
930	                | b'+'
931	                | b','
932	                | b'-'
933	                | b'.'
934	                | b'/'
935	                | b':'
936	                | b'='
937	                | b'?'
938	        ))
939	    }
