941	    /// Validate BMPString content: an even number of bytes read as big-endian
942	    /// 16-bit characters, each of which must be a Basic Multilingual Plane
943	    /// code point (U+0000..=U+FFFF) and never a UTF-16 surrogate
944	    /// (U+D800..=U+DFFF). Surrogates are not characters, so a lone high or
945	    /// low surrogate is corrupt, and so is an adjacent pair that UTF-16
946	    /// rules would combine into an astral-plane character — the pair must
947	    /// not be merged and displayed. An illegal value fails the whole
948	    /// certificate; bytes are never dropped or replaced to salvage it.
949	    /// Empty content stays legal, preserving the existing acceptance of
950	    /// empty values. `what` names the name being checked ("subject" or
951	    /// "issuer") so the error identifies the offending name.
952	    fn check_bmp_string(content: &[u8], what: &str) -> Result<(), String> {
953	        if content.len() % 2 != 0 {
954	            return Err(format!(
955	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
956	                 (the content must be a sequence of 16-bit characters)",
957	                content.len()
958	            ));
959	        }
960	        for pair in content.chunks_exact(2) {
961	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
962	            if (0xD800..=0xDFFF).contains(&unit) {
963	                return Err(format!(
964	                    "{what} name: BMPString attribute value contains the surrogate code \
965	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
966	                     are not characters and cannot appear, alone or in pairs)"
967	                ));
968	            }
969	        }
970	        Ok(())
971	    }
