973	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
974	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
975	        let s = match tag {
976	            0x0C => std::str::from_utf8(content)
977	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
978	                .to_string(),
979	            // ASCII-family strings: every byte is also its Unicode code point.
980	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
981	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
982	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
983	            0x1E => {
984	                if content.len() % 2 != 0 {
985	                    return Err("odd-length BMPString".to_string());
986	                }
987	                // A BMPString character is one big-endian 16-bit BMP code
988	                // point, never a UTF-16 surrogate: surrogate pairs must not
989	                // be merged into astral-plane characters.
990	                let mut s = String::with_capacity(content.len() / 2);
991	                for c in content.chunks_exact(2) {
992	                    let unit = u16::from_be_bytes([c[0], c[1]]);
993	                    let ch = char::from_u32(unit as u32)
994	                        .ok_or_else(|| "surrogate code point in BMPString".to_string())?;
995	                    s.push(ch);
996	                }
997	                s
998	            }
999	            0x1C => {
1000	                if content.len() % 4 != 0 {
1001	                    return Err("invalid UniversalString length".to_string());
1002	                }
1003	                let mut s = String::new();
1004	                for c in content.chunks_exact(4) {
1005	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
1006	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
1007	                        return Err("invalid code point in UniversalString".to_string());
1008	                    }
1009	                    s.push(char::from_u32(cp).unwrap());
1010	                }
1011	                s
1012	            }
1013	            _ => {
1014	                return Err(format!(
1015	                    "unsupported attribute value string type (tag 0x{tag:02X})"
1016	                ))
1017	            }
1018	        };
1019	        Ok(s)
1020	    }
