1022	    /// RFC 4514 value escaping; everything above the ASCII control range
1023	    /// (including CJK text) passes through unchanged.
1024	    fn escape_value(value: &str) -> String {
1025	        let mut out = String::with_capacity(value.len());
1026	        let last = value.chars().count().saturating_sub(1);
1027	        for (i, c) in value.chars().enumerate() {
1028	            let at_edge = i == 0 || i == last;
1029	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
1030	                || (at_edge && (c == ' ' || c == '#'));
1031	            if needs_backslash {
1032	                out.push('\\');
1033	                out.push(c);
1034	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
1035	                let mut buf = [0u8; 4];
1036	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
1037	                write!(out, "\\{b:02X}").unwrap();
1038	            } else {
1039	                out.push(c);
1040	            }
1041	        }
1042	        out
1043	    }
