1045	    fn format_time(tlv: Tlv) -> Result<String, String> {
1046	        let (y, mo, d, h, mi, se) = match tlv.tag {
1047	            TAG_UTC_TIME => {
1048	                let c = tlv.content;
1049	                if c.len() != 13 || c[12] != b'Z' {
1050	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
1051	                }
1052	                let digits = &c[..12];
1053	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1054	                    return Err("non-numeric UTCTime".to_string());
1055	                }
1056	                let n = |a: usize, b: usize| -> u32 {
1057	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1058	                };
1059	                let yy = n(0, 1);
1060	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
1061	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
1062	            }
1063	            TAG_GENERALIZED_TIME => {
1064	                let c = tlv.content;
1065	                if c.len() != 15 || c[14] != b'Z' {
1066	                    return Err(
1067	                        "GeneralizedTime must be YYYYMMDDHHMMSSZ in UTC".to_string()
1068	                    );
1069	                }
1070	                let digits = &c[..14];
1071	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1072	                    return Err("non-numeric GeneralizedTime".to_string());
1073	                }
1074	                let n = |a: usize, b: usize| -> u32 {
1075	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1076	                };
