558	    inner.extend_from_slice(&[0x0C, 0x05, 0x61, 0x62, 0x63]); // len 5, 3 present
559	    let subject = name(&[rdn(&[seq(&inner)])]);
560	    let issuer = simple_cn_name("Test CA");
561	    let (out, _cert) = run_inspect("truncated-value", &build_cert(&subject, &issuer));
562	
563	    assert_invalid_certificate(&out);
564	}
565	
566	#[test]
567	fn non_minimal_value_length_encoding_is_rejected() {
568	    // A three-byte value encoded as 0x81 0x03 is not valid DER.
569	    let mut inner = oid(&[1, 2, 3, 4]);
570	    inner.extend_from_slice(&[0x0C, 0x81, 0x03, 0x61, 0x62, 0x63]);
571	    let subject = name(&[rdn(&[seq(&inner)])]);
572	    let issuer = simple_cn_name("Test CA");
573	    let (out, _cert) = run_inspect("nonminimal-len", &build_cert(&subject, &issuer));
574	
575	    assert_invalid_certificate(&out);
576	}
577	
578	#[test]
579	fn truncated_certificate_file_is_rejected() {
580	    // Bytes cut off the tail of an otherwise valid certificate: malformed
581	    // input, same failure contract.
582	    let subject = simple_cn_name("subject.example");
583	    let issuer = simple_cn_name("Test CA");
584	    let mut bytes = build_cert(&subject, &issuer);
585	    bytes.truncate(bytes.len() - 5);
586	    let (out, _cert) = run_inspect("truncated-cert", &bytes);
587	
588	    assert_invalid_certificate(&out);
589	}
590	
591	// ----- DER SET OF ordering inside multi-valued RDNs ------------------------
592	
593	#[test]
594	fn unsorted_subject_multivalued_rdn_is_rejected() {
595	    // O and CN in one RDN, encoded O-first: both members have the same outer
596	    // tag and length, and O's OID arc byte 0x0A is greater than CN's 0x03, so
597	    // the SET OF is not byte-sorted. This must fail as a corrupt certificate
598	    // and name the subject, never be printed or repaired by reordering the
599	    // members (alphabetically "CN" would sort first, which is exactly the
600	    // kind of display-name comparison that must not be used).
601	    let subject = name(&[rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")])]);
602	    let issuer = simple_cn_name("Test CA");
603	    let (out, _cert) = run_inspect("bad-order-subject", &build_cert(&subject, &issuer));
604	
605	    assert_invalid_certificate(&out);
606	    let stderr = lossy(&out.stderr);
607	    assert!(
608	        stderr.contains("subject") && stderr.contains("order"),
609	        "reason must name the subject name and the ordering problem: {stderr}"
610	    );
611	}
612	
613	#[test]
614	fn unsorted_issuer_multivalued_rdn_is_rejected() {
615	    // Same violation in the issuer must be reported against the issuer name,
616	    // even though the subject is well-formed.
617	    let subject = simple_cn_name("subject.example");
618	    let issuer = name(&[rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")])]);
619	    let (out, _cert) = run_inspect("bad-order-issuer", &build_cert(&subject, &issuer));
620	
621	    assert_invalid_certificate(&out);
622	    let stderr = lossy(&out.stderr);
623	    assert!(
624	        stderr.contains("issuer") && stderr.contains("order"),
625	        "reason must name the issuer name and the ordering problem: {stderr}"
626	    );
627	}
628	
629	#[test]
630	fn ordering_compares_encoding_content_not_attribute_text() {
631	    // The same unknown OID twice (identical dotted text) with values "b" and
632	    // "a": both complete encodings have equal tag and length, and the first
633	    // value byte 0x62 > 0x61, so "b" before "a" is out of DER order. Sorting
634	    // by attribute name or value text would call these identical or sort the
635	    // same way only by accident; this pins the comparison to encoding bytes.
636	    let subject = name(&[rdn(&[
637	        atv_utf8(&[1, 2, 3, 4], "b"),
638	        atv_utf8(&[1, 2, 3, 4], "a"),
639	    ])]);
640	    let issuer = simple_cn_name("Test CA");
641	    let (out, _cert) = run_inspect("bad-order-content", &build_cert(&subject, &issuer));
642	
643	    assert_invalid_certificate(&out);
644	}
645	
646	#[test]
647	fn ordering_compares_outer_length_before_value_text() {
648	    // CN="z" (complete ATV encoding 10 bytes) and 1.2.3.4="aaa" (12 bytes,
649	    // because its value is longer): DER compares tag, then the outer length
650	    // byte, so the shorter CN member sorts first even though the decoded
651	    // value text "aaa" would come well before "z". A comparison based on
652	    // decoded values would reject this legal certificate.
653	    let subject = name(&[rdn(&[
654	        atv_utf8(CN, "z"),
655	        atv_utf8(&[1, 2, 3, 4], "aaa"),
656	    ])]);
657	    let issuer = simple_cn_name("Test CA");
658	    let (out, _cert) = run_inspect("order-by-length", &build_cert(&subject, &issuer));
659	
660	    assert_success(&out, "CN=z+1.2.3.4=#0C03616161", "CN=Test CA");
661	
662	    // The reverse encoding is corrupt: the longer outer encoding must not
663	    // come first, regardless of the '#' text representation.
664	    let subject = name(&[rdn(&[
665	        atv_utf8(&[1, 2, 3, 4], "aaa"),
666	        atv_utf8(CN, "z"),
667	    ])]);
668	    let (out, _cert) = run_inspect("order-by-length-bad", &build_cert(&subject, &issuer));
669	    assert_invalid_certificate(&out);
670	}
671	
672	#[test]
673	fn each_rdn_is_checked_independently() {
674	    // Two RDNs in one name: the first (outermost) group is fine, a later
675	    // group carries O-before-CN out of order (OID arc 0x0A > 0x03). The
676	    // whole name must be rejected rather than treated as one set or checked
677	    // only on a group of the checker's choosing.
678	    let subject = name(&[
679	        rdn(&[atv_utf8(C, "CN")]),
680	        rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")]),
681	    ]);
682	    let issuer = simple_cn_name("Test CA");
683	    let (out, _cert) = run_inspect("bad-order-second-rdn", &build_cert(&subject, &issuer));
684	
685	    assert_invalid_certificate(&out);
686	    assert!(lossy(&out.stderr).contains("subject"));
687	}
688	
689	#[test]
690	fn identical_adjacent_members_are_allowed_and_not_deduplicated() {
691	    // Two members with byte-for-byte identical complete encodings compare
692	    // equal and therefore satisfy the sorted SET OF rule; both must still
693	    // appear in the output (no merging, no false ordering failure).
694	    let subject = name(&[rdn(&[
695	        atv_utf8(CN, "dup"),
696	        atv_utf8(CN, "dup"),
697	    ])]);
698	    let issuer = simple_cn_name("Test CA");
699	    let (out, _cert) = run_inspect("dup-members", &build_cert(&subject, &issuer));
700	
701	    assert_success(&out, "CN=dup+CN=dup", "CN=Test CA");
702	}
703	
704	#[test]
705	fn single_attribute_rdn_always_satisfies_set_ordering() {
706	    // A SET OF with one member is trivially sorted, whatever the attribute
707	    // and value encodings are.
708	    let subject = name(&[
709	        rdn(&[atv_utf8(C, "CN")]),
710	        rdn(&[atv_utf8(O, "org")]),
711	        rdn(&[atv_utf8(CN, "host")]),
712	    ]);
713	    let issuer = simple_cn_name("Test CA");
714	    let (out, _cert) = run_inspect("single-member-rdns", &build_cert(&subject, &issuer));
715	
716	    assert_success(&out, "CN=host,O=org,C=CN", "CN=Test CA");
717	}
718	
719	// ----- CLI contract: usage, version and unreadable files ------------------
720	
721	#[test]
722	fn version_flag_keeps_its_output() {
723	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
724	        .arg("--version")
725	        .output()
726	        .expect("running chainview");
727	    assert_eq!(out.status.code(), Some(0));
728	    assert!(out.stderr.is_empty());
729	    assert_eq!(lossy(&out.stdout), "chainview 0.1.0\n");
730	}
731	
732	#[test]
733	fn missing_path_is_a_usage_error() {
734	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
735	        .arg("inspect")
736	        .output()
737	        .expect("running chainview");
738	    assert_eq!(out.status.code(), Some(2));
739	    assert!(out.stdout.is_empty());
740	    assert_eq!(
741	        lossy(&out.stderr),
742	        "Usage: chainview inspect <DER-FILE>\n       chainview --version\n"
743	    );
744	}
745	
746	#[test]
747	fn unreadable_file_keeps_its_error_contract() {
748	    let missing = std::env::temp_dir().join("chainview-name-test-definitely-missing.der");
749	    let _ = fs::remove_file(&missing);
750	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
751	        .arg("inspect")
752	        .arg(&missing)
753	        .output()
754	        .expect("running chainview");
755	    assert_eq!(out.status.code(), Some(2));
756	    assert!(out.stdout.is_empty());
757	    let stderr = lossy(&out.stderr);
758	    assert!(
759	        stderr.starts_with(&format!(
760	            "chainview: cannot read certificate file '{}': ",
761	            missing.display()
762	        )),
763	        "unexpected stderr: {stderr}"
764	    );
765	}
766	
767	// ----- Assertions / process plumbing --------------------------------------
768	
769	fn assert_success(out: &Output, subject: &str, issuer: &str) {
770	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
771	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
772	    assert_eq!(
773	        lossy(&out.stdout),
774	        format!(
775	            "Subject: {subject}\n\
776	             Issuer: {issuer}\n\
777	             Serial Number: {FIXED_SERIAL}\n\
778	             Not Before: {FIXED_NOT_BEFORE}\n\
779	             Not After: {FIXED_NOT_AFTER}\n"
780	        )
781	    );
782	}
783	
784	/// Every malformed-input case shares the documented contract: exit code 2,
785	/// nothing on stdout (so no name field can be printed before the error is
786	/// noticed), and the fixed invalid-certificate message prefix on stderr.
787	fn assert_invalid_certificate(out: &Output) {
788	    assert_eq!(
789	        out.status.code(),
790	        Some(2),
791	        "stdout={} stderr={}",
792	        lossy(&out.stdout),
793	        lossy(&out.stderr)
794	    );
795	    assert!(
796	        out.stdout.is_empty(),
797	        "stdout must be empty on failure, got: {}",
798	        lossy(&out.stdout)
799	    );
800	    let stderr = lossy(&out.stderr);
801	    assert!(
802	        stderr.starts_with("chainview: invalid DER certificate: "),
803	        "unexpected stderr: {stderr}"
804	    );
805	    // A non-empty reason after the fixed prefix.
806	    assert!(
807	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
808	        "missing error reason in stderr: {stderr}"
809	    );
810	}
811	
812	fn lossy(bytes: &[u8]) -> String {
813	    String::from_utf8_lossy(bytes).into_owned()
814	}
815	
816	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
817	    let cert = TempCert::new(tag, data);
818	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
819	        .arg("inspect")
820	        .arg(&cert.path)
821	        .output()
822	        .expect("running chainview");
823	    (output, cert)
824	}
825	
826	struct TempCert {
827	    path: PathBuf,
828	}
829	
830	impl TempCert {
831	    fn new(tag: &str, data: &[u8]) -> Self {
832	        static COUNTER: AtomicU64 = AtomicU64::new(0);
833	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
834	        let path = std::env::temp_dir().join(format!(
835	            "chainview-name-test-{}-{tag}-{unique}.der",
836	            std::process::id()
837	        ));
838	        fs::write(&path, data).expect("writing temp certificate");
839	        TempCert { path }
840	    }
841	}
842	
843	impl Drop for TempCert {
844	    fn drop(&mut self) {
845	        let _ = fs::remove_file(&self.path);
846	    }
847	}
848	
849	// ----- Certificate / DER construction -------------------------------------
850	//
851	// Only the structural pieces needed here. Lengths are always emitted in the
852	// minimal DER form, except where a test injects raw bytes to exercise
853	// rejection of non-minimal or truncated encodings.
854	
855	fn simple_cn_name(cn: &str) -> Vec<u8> {
856	    name(&[rdn(&[atv_utf8(CN, cn)])])
857	}
858	
859	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
860	/// validity and key material around the supplied Subject/Issuer names.
861	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
862	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
863	    let validity = seq(&concat(&[
864	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
865	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
866	    ]));
867	    let spki = seq(&concat(&[
868	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
869	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
870	    ]));
871	
872	    let tbs = seq(&concat(&[
873	        &serial,
874	        &signature_algorithm(),
875	        issuer,
876	        &validity,
877	        subject,
878	        &spki,
879	    ]));
880	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
881	}
882	
883	fn signature_algorithm() -> Vec<u8> {
884	    // sha256WithRSAEncryption with explicit NULL parameters.
885	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
886	}
887	
888	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
889	    tlv(
890	        0x30,
891	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
892	    )
893	}
894	
895	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
896	    tlv(
897	        0x31,
898	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
899	    )
900	}
901	
902	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
903	/// complete DER TLV of the value.
904	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
905	    seq(&concat(&[&oid(arcs), value]))
906	}
907	
908	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
909	    atv(arcs, &tlv(0x0C, text.as_bytes()))
910	}
911	
912	fn atv_printable(arcs: &[u64], bytes: &[u8]) -> Vec<u8> {
913	    atv(arcs, &tlv(0x13, bytes))
914	}
915	
916	fn atv_bmp(arcs: &[u64], content: &[u8]) -> Vec<u8> {
917	    atv(arcs, &tlv(0x1E, content))
918	}
919	
920	/// Big-endian 16-bit units, the wire form of a BMPString's characters.
921	fn bmp_units(units: &[u16]) -> Vec<u8> {
922	    units.iter().flat_map(|u| u.to_be_bytes()).collect()
923	}
924	
925	fn oid(arcs: &[u64]) -> Vec<u8> {
926	    assert!(arcs.len() >= 2);
927	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
928	    for &arc in &arcs[2..] {
929	        content.extend_from_slice(&oid_arc(arc));
930	    }
931	    tlv(0x06, &content)
932	}
933	
934	fn oid_arc(mut value: u64) -> Vec<u8> {
935	    let mut out = vec![(value % 128) as u8];
936	    value /= 128;
937	    while value > 0 {
938	        out.push(0x80 | (value % 128) as u8);
939	        value /= 128;
940	    }
941	    out.reverse();
942	    out
943	}
944	
945	fn seq(content: &[u8]) -> Vec<u8> {
946	    tlv(0x30, content)
947	}
948	
949	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
950	    let mut out = vec![tag];
951	    out.extend_from_slice(&der_len(content.len()));
952	    out.extend_from_slice(content);
953	    out
954	}
955	
956	fn der_len(n: usize) -> Vec<u8> {
957	    if n < 0x80 {
958	        vec![n as u8]
959	    } else {
960	        let mut body = Vec::new();
961	        let mut v = n;
962	        while v > 0 {
963	            body.push((v & 0xFF) as u8);
964	            v >>= 8;
965	        }
966	        body.reverse();
967	        let mut out = vec![0x80 | body.len() as u8];
968	        out.extend_from_slice(&body);
969	        out
970	    }
971	}
972	
973	fn concat(parts: &[&[u8]]) -> Vec<u8> {
974	    let mut out = Vec::new();
975	    for part in parts {
976	        out.extend_from_slice(part);
977	    }
978	    out
979	}
980	
981	fn hex(bytes: &[u8]) -> String {
982	    let mut s = String::with_capacity(bytes.len() * 2);
983	    for b in bytes {
984	        use std::fmt::Write;
985	        write!(s, "{b:02X}").unwrap();
986	    }
987	    s
988	}
